package eval

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"encoding/json"
	"fmt"
	"io"
	"sort"
	"strconv"
	"strings"
	"sync"
)

// The bundled, pre-parsed action snapshot lives alongside this package. It is
// generated by AWSHound's scripts/refresh_iam_actions.py (a maintainer step) and
// committed. Mirrors catalog.py's _BUNDLED_SNAPSHOT.
//
//go:embed data/aws_actions.json.gz
var bundledSnapshot []byte

// ActionCatalog expands IAM action patterns against the set of known AWS
// actions. It ports awshound/core/evaluation/iam_policy/catalog.py's
// ActionCatalog: principal-agnostic data used to expand wildcard actions
// ("s3:*", "iam:Get*", "*") and the NotAction complement.
//
// The catalog is read-only after construction and safe for concurrent use.
type ActionCatalog struct {
	// byService maps a lowercased service prefix to that service's
	// {CanonicalActionName: accessLevel}. Mirrors catalog.py's _by_service.
	byService map[string]map[string]string
	// canonical maps a lowercased service prefix to {loweredActionName:
	// CanonicalActionName}, for case-insensitive lookup that returns AWS's
	// canonical casing. Mirrors catalog.py's _canonical.
	canonical map[string]map[string]string

	// allActions is the materialized "service:Action" universe, computed once on
	// first use (for "*"/NotAction) and cached. Guarded by allOnce.
	allOnce    sync.Once
	allActions []string
}

// snapshotEnvelope is the on-disk provenance envelope. Only the actions map is
// read (the sibling provenance keys schema_version/source/generated_at are
// ignored); actions is {service: {action: access_level}}. The envelope-vs-flat
// detection keys on schema_version's presence in the raw JSON (see
// parseSnapshot), not on this struct.
type snapshotEnvelope struct {
	Actions map[string]map[string]string `json:"actions"`
}

// NewActionCatalog builds a catalog from an in-memory {service: {action:
// access_level}} mapping. Service prefixes are lowercased; action names keep
// AWS's canonical casing. Mirrors ActionCatalog.__init__ (no provenance).
func NewActionCatalog(actionsByService map[string]map[string]string) *ActionCatalog {
	c := &ActionCatalog{
		byService: make(map[string]map[string]string, len(actionsByService)),
		canonical: make(map[string]map[string]string, len(actionsByService)),
	}
	for service, actions := range actionsByService {
		svc := strings.ToLower(service)
		byName := make(map[string]string, len(actions))
		canon := make(map[string]string, len(actions))
		for name, access := range actions {
			byName[name] = access
			canon[strings.ToLower(name)] = name
		}
		// A later duplicate (post-lowercasing) service key wins, matching the
		// dict comprehension in catalog.py. AWS prefixes never collide in practice.
		c.byService[svc] = byName
		c.canonical[svc] = canon
	}
	return c
}

// LoadBundled loads the catalog from the snapshot bundled with the package.
// Mirrors ActionCatalog.load_bundled.
func LoadBundled() (*ActionCatalog, error) {
	return parseSnapshot(bundledSnapshot)
}

// parseSnapshot gunzips and JSON-parses a snapshot's raw bytes. An envelope
// (truthy "schema_version") carries provenance and its actions live under the
// "actions" key; otherwise the whole object is treated as the flat actions
// mapping. Mirrors the envelope-vs-flat detection in ActionCatalog.load.
func parseSnapshot(gzBytes []byte) (*ActionCatalog, error) {
	gz, err := gzip.NewReader(bytes.NewReader(gzBytes))
	if err != nil {
		return nil, fmt.Errorf("eval: open catalog gzip: %w", err)
	}
	defer gz.Close()
	data, err := io.ReadAll(gz)
	if err != nil {
		return nil, fmt.Errorf("eval: decompress catalog gzip: %w", err)
	}

	var probe map[string]json.RawMessage
	if err := json.Unmarshal(data, &probe); err != nil {
		return nil, fmt.Errorf("eval: parse catalog json: %w", err)
	}
	if sv, ok := probe["schema_version"]; ok && jsonTruthy(sv) {
		var env snapshotEnvelope
		if err := json.Unmarshal(data, &env); err != nil {
			return nil, fmt.Errorf("eval: parse catalog envelope: %w", err)
		}
		return NewActionCatalog(env.Actions), nil
	}

	var flat map[string]map[string]string
	if err := json.Unmarshal(data, &flat); err != nil {
		return nil, fmt.Errorf("eval: parse flat catalog: %w", err)
	}
	return NewActionCatalog(flat), nil
}

// jsonTruthy reports whether a JSON value is truthy in Python's sense, matching
// catalog.py's `raw.get("schema_version")` guard: null/false/0/empty are falsy,
// everything else (notably a nonzero schema version) is truthy.
func jsonTruthy(raw json.RawMessage) bool {
	switch s := strings.TrimSpace(string(raw)); s {
	case "", "null", "false", "0", "0.0", `""`, "[]", "{}":
		return false
	default:
		if f, err := strconv.ParseFloat(s, 64); err == nil {
			return f != 0
		}
		return true
	}
}

// Contains reports whether action is a known AWS action (case-insensitive).
// Mirrors ActionCatalog.__contains__.
func (c *ActionCatalog) Contains(action string) bool {
	service, name, _ := strings.Cut(action, ":")
	canon, ok := c.canonical[strings.ToLower(service)]
	if !ok {
		return false
	}
	_, ok = canon[strings.ToLower(name)]
	return ok
}

// AllActions returns every "service:Action" across every service, used to
// materialize the "*"/NotAction complement. The universe is computed once and
// cached; callers must treat the result as read-only. Mirrors
// ActionCatalog.all_actions.
func (c *ActionCatalog) AllActions() []string {
	c.allOnce.Do(func() {
		all := make([]string, 0, 1<<14)
		for svc, actions := range c.byService {
			for name := range actions {
				all = append(all, svc+":"+name)
			}
		}
		sort.Strings(all)
		c.allActions = all
	})
	return c.allActions
}

// ExpandPattern expands a single policy Action entry to the concrete actions it
// names. Mirrors ActionCatalog.expand:
//
//   - "*" expands to the whole action universe (AllActions). The engine resolves a
//     bare Action:["*"] symbolically via a complement grant (see statementActions),
//     so that hot path never materializes the ~20k-action catalog — but a
//     NotAction:["*"] statement (and any external caller) still reaches this branch,
//     which must return AllActions for parity with catalog.py.
//   - a service wildcard ("s3:*", "iam:Get*", "s3:Get?bject" — any entry whose
//     action part contains '*' or '?') expands via fnmatch against that service's
//     actions, returning canonical casing with a lowercased service prefix.
//   - a concrete "service:Action" resolves case-insensitively to canonical
//     casing, or, when unknown to the snapshot (newer than it), passes through as
//     "service:Action" with the service prefix lowercased so a policy referencing
//     it still produces a grant.
//
// The result is deduplicated (by construction) and sorted for determinism. As
// with catalog.py's frozenset return it must be treated as read-only — the "*"
// branch shares AllActions' cached slice.
func (c *ActionCatalog) ExpandPattern(pattern string) []string {
	if pattern == "*" {
		return c.AllActions()
	}
	service, name, _ := strings.Cut(pattern, ":")
	svc := strings.ToLower(service)

	if strings.ContainsAny(name, "*?") {
		cg := compileGlobCached(strings.ToLower(name))
		var out []string
		for canonicalName := range c.byService[svc] {
			if cg.match(strings.ToLower(canonicalName)) {
				out = append(out, svc+":"+canonicalName)
			}
		}
		sort.Strings(out)
		return out
	}

	if canon, ok := c.canonical[svc]; ok {
		if canonicalName, ok := canon[strings.ToLower(name)]; ok {
			return []string{svc + ":" + canonicalName}
		}
	}
	// Unknown action (newer than our snapshot): pass it through, service prefix
	// lowercased and action name left as written.
	return []string{svc + ":" + name}
}

// --- fnmatch-style glob matching -------------------------------------------
//
// catalog.py matches action patterns with fnmatch.fnmatchcase on already
// lowercased strings, which honors '*', '?' and '[seq]'/'[!seq]' character
// classes. RE2 (Go's regexp) lacks the atomic groups / lookahead that CPython's
// fnmatch.translate emits, so we match directly with a linear two-pointer star
// algorithm — same result set, no catastrophic backtracking. Character-class
// support is dormant on real IAM data (action names and patterns are
// alphanumeric plus '*'/'?') but kept for faithful fnmatch parity.

const (
	agLiteral uint8 = iota // matches one specific rune
	agAny                  // '?' — matches any one rune
	agStar                 // '*' — matches any run of runes (incl. empty)
	agClass                // '[...]' — matches one rune per the class body
)

type actionGlobToken struct {
	kind  uint8
	r     rune   // agLiteral
	class []rune // agClass: raw body between '[' and ']' (may start with '!')
}

// globMatchKind classifies a compiled fnmatch pattern into a fast-path shape. The
// overwhelming majority of real IAM patterns (StringLike/ArnLike condition values,
// service action wildcards) are a plain literal, a "prefix*", a "*suffix", or the
// bare "*"; each of those matches with a single strings call on the original bytes,
// avoiding the []rune conversion and the general two-pointer scan that dominated
// CPU (matchActionGlob was the single hottest function on policy-heavy accounts).
type globMatchKind uint8

const (
	globGeneral globMatchKind = iota // needs the tokenized matcher (?, [class], interior *)
	globAny                          // "*" — matches everything
	globLiteral                      // no wildcards — exact equality
	globPrefix                       // "lit*" — one trailing star, no other metachars
	globSuffix                       // "*lit" — one leading star, no other metachars
)

// compiledGlob is a memoised fnmatch pattern: a fast-path classification plus the
// tokenized form for the general case. Read-only after construction, so a single
// shared entry is safe for concurrent matchers.
type compiledGlob struct {
	kind    globMatchKind
	literal string            // globLiteral/globPrefix/globSuffix: the fixed run
	toks    []actionGlobToken // globGeneral only
}

// match reports whether name matches the compiled pattern. The fast paths use byte
// string operations (correct for the fixed-run cases regardless of encoding); the
// general path defers to the rune-based two-pointer matcher. Semantics are
// identical to matchActionGlob([]rune(name), compileActionGlob([]rune(pattern))).
func (c compiledGlob) match(name string) bool {
	switch c.kind {
	case globAny:
		return true
	case globLiteral:
		return name == c.literal
	case globPrefix:
		return strings.HasPrefix(name, c.literal)
	case globSuffix:
		return strings.HasSuffix(name, c.literal)
	default:
		return matchActionGlob([]rune(name), c.toks)
	}
}

// compiledGlobCache memoizes compileGlobCached by pattern string.
//
// This mirrors CPython fnmatch's module-level lru_cache on the compiled pattern.
// operators.py's string_like matches via fnmatch.fnmatchcase, which compiles each
// pattern once and reuses it; without this cache the Go StringLike recompiled the
// glob on every (principal × resource) condition check, which on policy-heavy
// accounts dominated CPU (repeated token-slice allocation) and drove the GC.
var compiledGlobCache sync.Map // map[string]compiledGlob

// compileGlobCached returns the compiled, classified pattern, memoised across
// calls. Use this on any hot path that matches the same patterns repeatedly (the
// StringLike/ArnLike condition atoms, action-pattern expansion).
func compileGlobCached(pattern string) compiledGlob {
	if v, ok := compiledGlobCache.Load(pattern); ok {
		return v.(compiledGlob)
	}
	cg := classifyGlob(pattern)
	compiledGlobCache.Store(pattern, cg)
	return cg
}

// classifyGlob determines a pattern's fast-path shape, falling back to the general
// tokenized matcher for anything with a '?', a '[' class, or an interior '*'.
func classifyGlob(pattern string) compiledGlob {
	if pattern == "*" {
		return compiledGlob{kind: globAny}
	}
	if !strings.ContainsAny(pattern, "*?[") {
		return compiledGlob{kind: globLiteral, literal: pattern}
	}
	// Single '*' with no other metachars: a prefix or suffix test. (A '[' or '?'
	// anywhere, or more than one '*', drops to the general matcher.)
	if !strings.ContainsAny(pattern, "?[") && strings.Count(pattern, "*") == 1 {
		if rest, ok := strings.CutSuffix(pattern, "*"); ok {
			return compiledGlob{kind: globPrefix, literal: rest}
		}
		if rest, ok := strings.CutPrefix(pattern, "*"); ok {
			return compiledGlob{kind: globSuffix, literal: rest}
		}
	}
	return compiledGlob{kind: globGeneral, toks: compileActionGlob([]rune(pattern))}
}

// compileActionGlob parses an fnmatch pattern into tokens, mirroring the scan in
// CPython's fnmatch._translate: consecutive '*' collapse to one; a ']'
// immediately after '[' or '[!' is a literal class member; an unclosed '[' is a
// literal '['.
func compileActionGlob(pat []rune) []actionGlobToken {
	var toks []actionGlobToken
	i, n := 0, len(pat)
	for i < n {
		c := pat[i]
		i++
		switch c {
		case '*':
			if len(toks) == 0 || toks[len(toks)-1].kind != agStar {
				toks = append(toks, actionGlobToken{kind: agStar})
			}
		case '?':
			toks = append(toks, actionGlobToken{kind: agAny})
		case '[':
			j := i
			if j < n && pat[j] == '!' {
				j++
			}
			if j < n && pat[j] == ']' {
				j++
			}
			for j < n && pat[j] != ']' {
				j++
			}
			if j >= n {
				// Unclosed class: treat '[' as a literal (fnmatch adds '\\[').
				toks = append(toks, actionGlobToken{kind: agLiteral, r: '['})
			} else {
				toks = append(toks, actionGlobToken{kind: agClass, class: pat[i:j]})
				i = j + 1
			}
		default:
			toks = append(toks, actionGlobToken{kind: agLiteral, r: c})
		}
	}
	return toks
}

// matchActionGlob reports whether name matches the compiled tokens. Each
// non-star token consumes exactly one rune; a star greedily consumes runs with a
// single backtrack point, giving linear-time matching.
func matchActionGlob(name []rune, toks []actionGlobToken) bool {
	ni, ti := 0, 0
	starTi, starNi := -1, -1
	for ni < len(name) {
		if ti < len(toks) && toks[ti].kind == agStar {
			starTi, starNi = ti, ni
			ti++
			continue
		}
		if ti < len(toks) && matchActionGlobToken(toks[ti], name[ni]) {
			ni++
			ti++
			continue
		}
		if starTi >= 0 {
			ti = starTi + 1
			starNi++
			ni = starNi
			continue
		}
		return false
	}
	for ti < len(toks) && toks[ti].kind == agStar {
		ti++
	}
	return ti == len(toks)
}

func matchActionGlobToken(t actionGlobToken, ch rune) bool {
	switch t.kind {
	case agAny:
		return true
	case agLiteral:
		return t.r == ch
	case agClass:
		return matchActionGlobClass(t.class, ch)
	default: // agStar is handled by matchActionGlob
		return false
	}
}

// matchActionGlobClass interprets an fnmatch character-class body (the text
// between '[' and ']', a leading '!' negating) against ch, honoring 'a-z'
// ranges. A '-' with no following member (leading or trailing) is a literal.
func matchActionGlobClass(class []rune, ch rune) bool {
	s := class
	negate := false
	if len(s) > 0 && s[0] == '!' {
		negate = true
		s = s[1:]
	}
	matched := false
	for k := 0; k < len(s); {
		if k+2 < len(s) && s[k+1] == '-' {
			if s[k] <= ch && ch <= s[k+2] {
				matched = true
			}
			k += 3
		} else {
			if s[k] == ch {
				matched = true
			}
			k++
		}
	}
	return matched != negate
}
